/**
 * ADR-296 Phase 5 · 사용자 결정 3 — the Library origins a project's pages use, as files: a locked one
 * is `node_modules/@composition/library/<Name>.tsx` (read only — editing it is refused; 「Unlock」 runs
 * ADR-282 `unlockOrigin`), an unlocked one (its template copied into the project's nodes) is a user
 * component's file, `src/components/<Name>.tsx` (origin commands on the copy). Both are generated by
 * the component generator over a reader that shows the origin as a definition and a locked
 * template's nodes as document nodes.
 */
import type {
  CatalogReader,
  DefinitionEntry,
  NodeEntry,
  PageEntry,
  ProjectEntry,
  WriteValue,
} from "../../catalog/document/types";
import { pascal } from "./names";

type Reader = Pick<CatalogReader, "projectId" | "getEntry" | "library">;

export const CODE_VIEW_LIBRARY_DIR = "node_modules/@composition/library";

export interface CodeViewLibraryOrigin {
  readonly id: string;
  readonly name: string;
  /** Still the Library's template (unlock to edit). */
  readonly locked: boolean;
}

/** The composite Library origins the pages' nodes are instances of (tree order). */
export function codeViewLibraryOrigins(
  reader: Reader,
): CodeViewLibraryOrigin[] {
  const project = reader.getEntry(reader.projectId) as ProjectEntry;
  const used = new Set<string>();
  const walk = (ids: readonly string[]) => {
    for (const id of ids) {
      const node = reader.getEntry(id) as NodeEntry | undefined;
      if (node?.kind !== "node") continue;
      if (node.definitionId.startsWith("lib:")) used.add(node.definitionId);
      walk(node.children);
    }
  };
  for (const id of project.pageIds) {
    const page = reader.getEntry(id) as PageEntry | undefined;
    if (page?.kind === "page") walk(page.children);
  }
  const out: CodeViewLibraryOrigin[] = [];
  const taken = new Set<string>();
  for (const id of [...used].sort()) {
    const definition = reader.library.definitions.get(id as never);
    if (definition?.mode !== "composite" || !definition.templateRootId)
      continue;
    let name = pascal(definition.name, "Origin");
    for (let index = 2; taken.has(name); index += 1)
      name = `${pascal(definition.name, "Origin")}${index}`;
    taken.add(name);
    out.push({
      id,
      name,
      locked: definition.templateRootId.startsWith("lib:template:"),
    });
  }
  return out;
}

const set = <T>(value: T): WriteValue<T> => ({ kind: "set", value });
const writes = (values: Readonly<Record<string, unknown>> | undefined) =>
  Object.fromEntries(
    Object.entries(values ?? {}).map(([key, value]) => [key, set(value)]),
  );

/**
 * A reader that shows a Library origin as a definition (its template root — the copy once
 * unlocked) and a locked template's nodes as document nodes (their values as writes).
 */
export function codeViewLibraryReader<R extends Reader>(reader: R): R {
  const getEntry = (id: string) => {
    if (id.startsWith("lib:definition:")) {
      const definition = reader.library.definitions.get(id as never);
      if (definition?.mode === "composite" && definition.templateRootId)
        return {
          kind: "definition",
          id,
          name: definition.name,
          mode: "composite",
          accepts: {},
          defaults: {},
          visual: {},
          stateRules: {},
          templateRootId: definition.templateRootId,
        } as unknown as DefinitionEntry;
    }
    if (id.startsWith("lib:template:")) {
      const node = reader.library.templates.get(id as never);
      if (!node) return undefined;
      return {
        kind: "node",
        id,
        definitionId: node.definitionId,
        children: node.children,
        props: writes(node.props),
        visual: writes(node.visual),
        sizing: {},
        ...(node.layout ? { layout: writes(node.layout) } : {}),
        ...(node.enabled === false ? { enabled: false } : {}),
        descendantOverrides: [],
      } as unknown as NodeEntry;
    }
    return reader.getEntry(id);
  };
  return new Proxy(reader, {
    get(target, property) {
      if (property === "getEntry") return getEntry;
      const value = Reflect.get(target, property, target);
      return typeof value === "function" ? value.bind(target) : value;
    },
  });
}

/**
 * A Library origin's project defaults (`definitionOverride` defaults · visual · state rules — the
 * Components panel's): a read-only comment line, or undefined when it has none.
 */
export function codeViewLibraryDefaults(
  reader: Reader,
  definitionId: string,
): string | undefined {
  if (!definitionId.startsWith("lib:")) return undefined;
  const project = reader.getEntry(reader.projectId) as ProjectEntry;
  for (const id of project.overrideIds ?? []) {
    const override = reader.getEntry(id) as
      | {
          kind?: string;
          targetId?: string;
          defaults?: object;
          visual?: object;
          stateRules?: object;
        }
      | undefined;
    if (
      override?.kind !== "definitionOverride" ||
      override.targetId !== definitionId
    )
      continue;
    const parts = Object.fromEntries(
      (["defaults", "visual", "stateRules"] as const)
        .filter((key) => Object.keys(override[key] ?? {}).length)
        .map((key) => [key, override[key]]),
    );
    return Object.keys(parts).length
      ? `// composition: this project's defaults for the component — ${JSON.stringify(parts)} (Components panel, read only)`
      : undefined;
  }
  return undefined;
}
